CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, email text UNIQUE, phone text UNIQUE, pin_hash text NOT NULL, avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (email IS NOT NULL OR phone IS NOT NULL));
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text DEFAULT '', created_by uuid NOT NULL REFERENCES users(id), invite_code text UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(12),'hex'), archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS group_members (group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'member' CHECK (role IN ('admin','member')), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS group_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, token text UNIQUE NOT NULL DEFAULT encode(gen_random_bytes(24),'hex'), created_by uuid NOT NULL REFERENCES users(id), expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id), title text NOT NULL, notes text DEFAULT '', expense_date date NOT NULL DEFAULT CURRENT_DATE, created_by uuid NOT NULL REFERENCES users(id), subtotal_paise bigint NOT NULL DEFAULT 0, tax_paise bigint NOT NULL DEFAULT 0, service_charge_paise bigint NOT NULL DEFAULT 0, discount_paise bigint NOT NULL DEFAULT 0, rounding_paise bigint NOT NULL DEFAULT 0, total_paise bigint NOT NULL DEFAULT 0, receipt_url text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','deleted')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expense_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_id uuid NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, name text NOT NULL, quantity numeric(10,2) NOT NULL DEFAULT 1, unit_price_paise bigint NOT NULL DEFAULT 0, base_total_paise bigint NOT NULL DEFAULT 0, tax_paise bigint NOT NULL DEFAULT 0, service_charge_paise bigint NOT NULL DEFAULT 0, discount_paise bigint NOT NULL DEFAULT 0, total_paise bigint NOT NULL DEFAULT 0, sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS expense_item_shares (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES expense_items(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), amount_paise bigint NOT NULL DEFAULT 0, UNIQUE(item_id,user_id));
CREATE TABLE IF NOT EXISTS expense_adjustments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_id uuid NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('tax','service_charge','discount','rounding')), label text NOT NULL, amount_paise bigint NOT NULL);
CREATE TABLE IF NOT EXISTS expense_payers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_id uuid NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), amount_paise bigint NOT NULL CHECK(amount_paise >= 0), UNIQUE(expense_id,user_id));
CREATE TABLE IF NOT EXISTS settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id), payer_id uuid NOT NULL REFERENCES users(id), receiver_id uuid NOT NULL REFERENCES users(id), amount_paise bigint NOT NULL CHECK(amount_paise > 0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','payer_marked','confirmed','rejected','reversed')), note text DEFAULT '', reference text, created_at timestamptz NOT NULL DEFAULT now(), payer_marked_at timestamptz, confirmed_at timestamptz, CHECK(payer_id <> receiver_id));
CREATE TABLE IF NOT EXISTS activity_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, entity_type text, entity_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, group_id uuid REFERENCES groups(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_group_members_user ON group_members(user_id);
CREATE INDEX IF NOT EXISTS idx_expenses_group_date ON expenses(group_id, expense_date DESC);
CREATE INDEX IF NOT EXISTS idx_item_shares_user ON expense_item_shares(user_id);
CREATE INDEX IF NOT EXISTS idx_settlements_group ON settlements(group_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_activity_group ON activity_logs(group_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS auth_login_attempts (identifier text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_started_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz);
